342:  [ "$(jq -r '.by_suite_version["1"].decisions | length' "$J")" -eq 9 ]   # the nine components (cycle-131 arms included; eval_only excluded)
764:@test "AR-48 the decision statistic is defect_catch_rate with defect_catch_rate_pm3 and _pm3_v1 printed beside every catch read (H1 and components), deciding nothing" {

